-- Top popular careers refresh for 2026.
-- Intent: add high-demand career profiles with no image dependency so the site uses
-- the existing professional fallback avatar. Content is structured for AIO, AEO,
-- SEO, GEO and LLMO with answer-first summaries, descriptive headings and
-- internal entity links.

UPDATE public.career_profiles
SET image = ''
WHERE COALESCE(image, '') <> '';

WITH careers(slug, name, domain, short_description, description, page_summary, avg_salary, growth, experience_required, top_skills, top_companies, related_courses, related_exams, job_roles, icon_emoji, meta_title, meta_description, meta_keywords, is_featured, display_order) AS (
  VALUES
  (
    'ai-ml-engineer',
    'AI and Machine Learning Engineer',
    'Artificial Intelligence',
    'AI and Machine Learning Engineers build models, agents and automation systems that help products make smarter decisions.',
    $career$<h2>What does an AI and Machine Learning Engineer do?</h2><p>An AI and Machine Learning Engineer designs, trains, evaluates and ships intelligent systems. The role is popular in 2026 because companies are adding AI copilots, recommendation engines, fraud models, vision systems and workflow automation to real products.</p><h2>Best-fit students</h2><p>This career suits students who enjoy mathematics, coding, experiments and practical problem solving. A strong path usually starts with <a href="/courses/btech">B.Tech</a>, <a href="/courses/bca">BCA</a>, <a href="/courses/mca">MCA</a> or a data science focused postgraduate course.</p><h2>Skills to build first</h2><p>Start with Python, statistics, linear algebra, SQL, model evaluation, prompt engineering, MLOps basics and responsible AI. Build projects that solve visible problems instead of only copying notebooks.</p><h2>Career outlook</h2><p>Demand is strong across product companies, banks, health-tech, edtech, logistics and consulting. Entry roles may begin as machine learning engineer, AI engineer, NLP engineer, computer vision engineer or applied scientist.</p><h2>FAQ</h2><h3>Is AI engineering good for freshers?</h3><p>Yes, if the fresher has real projects, coding strength and an ability to explain model choices clearly.</p><h3>Which course is useful?</h3><p>Computer science, data science, statistics and electronics routes can all work when backed by practical AI projects.</p>$career$,
    'AI and Machine Learning Engineer is a high-growth technology career for students who want to build intelligent products, agents and automation systems. Focus on Python, statistics, model evaluation, MLOps and responsible AI projects.',
    '₹8 - 35 LPA',
    'Very High',
    '0 - 2 years for junior roles; 3+ years for production ML ownership',
    ARRAY['Python','Machine Learning','Deep Learning','Statistics','MLOps','Prompt Engineering','Model Evaluation'],
    ARRAY['Google','Microsoft','Amazon','TCS','Infosys','Fractal','Razorpay','Flipkart'],
    ARRAY['btech','bca','mca','msc'],
    ARRAY['jee-main','gate','cuet'],
    '[{"title":"AI Engineer","level":"Entry to Mid"},{"title":"Machine Learning Engineer","level":"Entry to Senior"},{"title":"NLP Engineer","level":"Mid"},{"title":"Computer Vision Engineer","level":"Mid"}]'::jsonb,
    '🤖',
    'AI and Machine Learning Engineer Career Scope 2026',
    'Explore AI and Machine Learning Engineer salary, skills, courses, exams, job roles and career scope for Indian students in 2026.',
    'AI engineer career, machine learning engineer, AI jobs India, ML engineer salary, AI courses',
    true,
    1
