INSERT INTO public.career_profiles (
  slug, name, domain, short_description, description, page_summary,
  avg_salary, growth, experience_required, top_skills, top_companies,
  related_courses, related_exams, job_roles, image, icon_emoji,
  meta_title, meta_description, meta_keywords,
  status, is_featured, is_active, display_order, updated_at
)
SELECT
  slug, name, domain, short_description, description, page_summary,
  avg_salary, growth, experience_required, top_skills, top_companies,
  related_courses, related_exams, job_roles, ''::text, icon_emoji,
  meta_title, meta_description, meta_keywords,
  'Published', is_featured, true, display_order, now()
FROM careers
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  domain = EXCLUDED.domain,
  short_description = EXCLUDED.short_description,
  description = EXCLUDED.description,
  page_summary = EXCLUDED.page_summary,
  avg_salary = EXCLUDED.avg_salary,
  growth = EXCLUDED.growth,
  experience_required = EXCLUDED.experience_required,
  top_skills = EXCLUDED.top_skills,
  top_companies = EXCLUDED.top_companies,
  related_courses = EXCLUDED.related_courses,
  related_exams = EXCLUDED.related_exams,
  job_roles = EXCLUDED.job_roles,
  image = '',
  icon_emoji = EXCLUDED.icon_emoji,
  meta_title = EXCLUDED.meta_title,
  meta_description = EXCLUDED.meta_description,
  meta_keywords = EXCLUDED.meta_keywords,
  status = 'Published',
  is_featured = EXCLUDED.is_featured,
  is_active = true,
  display_order = EXCLUDED.display_order,
  updated_at = now();

INSERT INTO public.career_course_links (career_slug, course_slug)
SELECT c.slug, course_slug
FROM careers c
CROSS JOIN LATERAL unnest(c.related_courses) AS course_slug
ON CONFLICT (career_slug, course_slug) DO NOTHING;
